"""
    Checks relative (%) difference <floor between x and y
    floor would be a decimal value, e.g. 0.05
    """
def reldiff(x: Any, y: Any, floor: Any = None) -> object {
    d = x - y;
    if not d {
        return 0;
    }
    ref = x or y;
    d = float(d) / ref;
    return d if not floor else (0, d)[(abs(d) >= floor)];
}

"""
    A numerically stable algorithm is given below. It also computes the mean.
    This algorithm is due to Knuth,[1] who cites Welford.[2]
    n = 0
    mean = 0
    M2 = 0

    foreach x in data:
      n = n + 1
      delta = x - mean
      mean = mean + delta/n
      M2 = M2 + delta*(x - mean)      // This expression uses the new value of mean
    end for

    variance_n = M2/n
    variance = M2/(n - 1)
    """
def calcMeanSD(useme: Any) -> object {
    mean = 0.0;
    M2 = 0.0;
    sd = 0.0;
    n = len(useme);
    if (n > 1) {
        for (i, x) in enumerate(useme) {
            delta = x - mean;
            mean = mean + (delta / (i + 1));
            M2 = M2 + (delta * (x - mean));
        }
        variance = M2 / (n - 1);
        sd = pow(variance, 0.5);
    }
    return (mean, sd);
}

""" resolve multiple levels of generators """
def _resolve_nested(level_count: Any, source: Any) -> object {
    assert (level_count > 0);
    if (level_count > 1) {
        return [_resolve_nested((level_count - 1), item) for item in source];
    } else {
        return `list(source);
    }
}

